// PostToolUse hook generated by bootstrap-orchestrateur v2.
// 1. Flags en dash (U+2013) and em dash (U+2014) on lines the agent added.
//    Tracked file with a HEAD: only lines added or modified since HEAD are checked,
//    so pre-existing dashes never block. Otherwise (untracked file, no git, no commit
//    yet): only the text written by this tool call is checked.
// 2. Flags docs/plans/ACTIVE.md when it exceeds the line cap.
// Exit code 2 sends stderr back to Claude so it fixes the file itself.
// With --staged, runs the same checks on the git index instead: pre-commit safety net
// for writes this hook cannot see (Bash redirections, manual edits). Exit code 1.
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, resolve } from "node:path";

// Built from code points so no tool can silently turn the pattern into literal dashes.
const FORBIDDEN = new RegExp("[" + String.fromCharCode(0x2013, 0x2014) + "]");
// Paths where dashes are legitimate: product copy and archived legacy files.
// Ce backend n'a aucun dossier de traduction (pas de l10n, locales, i18n ni .arb) :
// seule l'archive des plans est exemptée.
const DASH_ALLOW = [
  /docs[\\/]plans[\\/]archive[\\/]/,
];
const ACTIVE_PATH = /docs[\\/]plans[\\/]ACTIVE\.md$/;
const ACTIVE_MAX_LINES = 150;

function git(args, cwd) {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    maxBuffer: 256 * 1024 * 1024,
    stdio: ["ignore", "pipe", "ignore"],
  });
}

// Leading slash so repo-relative paths ("l10n/fr.arb") match the patterns too.
function isDashAllowed(path) {
  return DASH_ALLOW.some((r) => r.test("/" + path));
}

// Maps each file of a -U0 unified diff to its added lines (line number -> text).
function addedLinesByFile(diff) {
  const byFile = new Map();
  let current = null;
  let inHeader = false;
  let cursor = 0;
  for (const line of diff.split("\n")) {
    if (line.startsWith("diff --git ")) {
      inHeader = true;
      current = null;
      continue;
    }
    if (inHeader) {
      if (line.startsWith("+++ ")) {
        const path = line.slice(4).replace(/\t$/, "");
        current = path === "/dev/null" ? null : path.replace(/^b\//, "");
        if (current) byFile.set(current, new Map());
      }
      if (!line.startsWith("@@")) continue;
      inHeader = false;
    }
    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
    if (hunk) {
      cursor = Number(hunk[1]);
      continue;
    }
    if (current && line.startsWith("+")) {
      byFile.get(current).set(cursor, line.slice(1));
      cursor++;
    }
  }
  return byFile;
}

// Pre-commit safety net: checks the git index, whoever wrote the files.
function checkStaged() {
  const cwd = process.cwd();
  const problems = [];
  let diff = "";
  try {
    diff = git(
      ["-c", "core.quotePath=false", "diff", "--cached", "--no-color", "-U0", "--diff-filter=ACMR"],
      cwd
    );
  } catch {
    return 0; // not a git repo: nothing to check
  }
  const byFile = addedLinesByFile(diff);
  for (const [path, added] of byFile) {
    if (isDashAllowed(path)) continue;
    for (const [n, text] of added) {
      if (FORBIDDEN.test(text)) {
        problems.push(`${path}:${n} en/em dash (forbidden, see docs/ORCHESTRATOR.md section 4)`);
      }
    }
  }
  // Only when this commit adds lines to ACTIVE.md: an unrelated commit, or one that
  // only removes lines (partial compaction), must not be blocked.
  let active = "";
  if ([...byFile].some(([p, added]) => ACTIVE_PATH.test("/" + p) && added.size > 0)) {
    try {
      active = git(["show", ":docs/plans/ACTIVE.md"], cwd);
    } catch {
      // ACTIVE.md not in the index: nothing to check.
    }
  }
  if (active) {
    // A trailing newline would otherwise count as one extra line.
    const count = active.replace(/\n$/, "").split("\n").length;
    if (count > ACTIVE_MAX_LINES) {
      problems.push(
        `docs/plans/ACTIVE.md has ${count} lines (max ${ACTIVE_MAX_LINES}): compact it, see docs/ORCHESTRATOR.md section 9`
      );
    }
  }
  if (problems.length) {
    console.error("Commit refused by the orchestrator safety net:\n" + problems.join("\n"));
    console.error("Intentional bypass: git commit --no-verify");
    return 1;
  }
  return 0;
}

if (process.argv.includes("--staged")) process.exit(checkStaged());

let input;
try {
  input = JSON.parse(readFileSync(0, "utf8")).tool_input ?? {};
} catch {
  process.exit(0);
}
if (!input.file_path) process.exit(0);
// Absolute path: git runs from the file's folder, a relative path would not match.
const file = resolve(input.file_path);

let text;
try {
  text = readFileSync(file, "utf8");
} catch {
  process.exit(0);
}

// Line numbers added or modified since HEAD, or null when git cannot tell.
function addedLinesSinceHead() {
  let diff;
  try {
    diff = git(["diff", "--no-color", "-U0", "HEAD", "--", file], dirname(file));
  } catch {
    return null; // no commit yet, or not a git repo
  }
  if (!diff) {
    // Empty diff is ambiguous: untracked file, or tracked and identical to HEAD.
    try {
      git(["ls-files", "--error-unmatch", "--", file], dirname(file));
    } catch {
      return null; // untracked
    }
    return new Set();
  }
  const [added] = addedLinesByFile(diff).values();
  return new Set(added ? added.keys() : []);
}

// Fallback: only the text written by this tool call (Write, Edit, MultiEdit).
function writtenLines() {
  return [
    input.content,
    input.new_string,
    ...(Array.isArray(input.edits) ? input.edits.map((e) => e.new_string) : []),
  ]
    .filter((s) => typeof s === "string")
    .join("\n")
    .split("\n");
}

// A trailing newline would otherwise count as one extra line.
const lines = text.replace(/\n$/, "").split("\n");
const problems = [];

if (!isDashAllowed(file)) {
  const added = addedLinesSinceHead();
  if (added) {
    lines.forEach((line, i) => {
      if (added.has(i + 1) && FORBIDDEN.test(line)) {
        problems.push(`${file}:${i + 1} en/em dash (forbidden, see docs/ORCHESTRATOR.md section 4)`);
      }
    });
  } else {
    for (const line of writtenLines()) {
      if (FORBIDDEN.test(line)) {
        problems.push(`${file}: en/em dash in "${line.trim().slice(0, 80)}" (forbidden, see docs/ORCHESTRATOR.md section 4)`);
      }
    }
  }
}

if (ACTIVE_PATH.test(file) && lines.length > ACTIVE_MAX_LINES) {
  problems.push(
    `${file} has ${lines.length} lines (max ${ACTIVE_MAX_LINES}): compact it now, see docs/ORCHESTRATOR.md section 9`
  );
}

if (problems.length) {
  console.error(problems.join("\n"));
  process.exit(2);
}
